import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Build lightweight scans over history
    opp_c = 0
    opp_d = 0
    me_c = 0
    me_d = 0
    for (me, op) in history:
        if op == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if me == 'C':
            me_c += 1
        else:
            me_d += 1

    last_my, last_op = history[-1]
    rounds_left = 100 - n

    # --- Early game: build cooperation, but don't be a total sucker ---
    if n <= 2:
        # If opponent opened defect, mirror once, otherwise cooperate.
        if opp_d > 0:
            return 'D'
        return 'C'

    opp_rate = opp_c / float(n)

    # --- Endgame: shift to selfish play when profitable ---
    if rounds_left <= 0:
        return 'D'

    if rounds_left <= 3:
        # Cooperative opponent worth milking; defective one we just defect.
        if opp_rate >= 0.85 and opp_d <= 1:
            if rounds_left == 1:
                return 'D'
            return 'C'
        return 'D'

    if rounds_left <= 8:
        if opp_rate >= 0.9 and opp_d == 0:
            # Almost pure cooperator: defect for the tail.
            return 'D'
        if opp_rate >= 0.7:
            if rng.random() < 0.5:
                return 'D'
            return 'C'
        return 'D'

    # --- Detect near-pure archetypes ---
    if n >= 10:
        if opp_d == 0:
            # Always cooperator: exploit hard but keep some C to be safe
            # in case it's a slightly perturbed reactive strategy.
            if n < 85:
                if rng.random() < 0.95:
                    return 'D'
                return 'C'
            return 'D'
        if opp_c == 0:
            # Always defector: defect back, rare probe (no noise, so rare is fine)
            if n < 90 and rng.random() < 0.02:
                return 'C'
            return 'D'

    # --- Streak analysis ---
    run_op_d = 0
    for (me, op) in reversed(history):
        if op == 'D':
            run_op_d += 1
        else:
            break
    run_op_c = 0
    for (me, op) in reversed(history):
        if op == 'C':
            run_op_c += 1
        else:
            break

    # If we've defected several in a row, consider easing back to C
    run_my_d = 0
    for (me, op) in reversed(history):
        if me == 'D':
            run_my_d += 1
        else:
            break

    # --- Reactive high-cooperation opponents: TFT-like with forgiveness ---
    if opp_rate >= 0.75:
        if last_op == 'D':
            # Forgive a lone defection after a cooperative run.
            if run_op_d == 1 and n >= 6 and rng.random() < 0.7:
                return 'C'
            if run_op_d >= 2:
                return 'D'
            return 'D'
        # Opponent cooperated.
        if last_my == 'D':
            # Return to cooperation to preserve mutual benefit.
            return 'C'
        # Occasional probe if we've had a long mutual-C run.
        if n >= 20 and run_op_c >= 6 and run_my_d == 0:
            if rng.random() < 0.06:
                return 'D'
        return 'C'

    # --- Moderate cooperation opponent: cautious reciprocation ---
    if opp_rate >= 0.4:
        if last_op == 'D':
            if run_op_d >= 3:
                return 'D'
            # Retaliate but avoid endless DD.
            if run_my_d >= 4:
                return 'C'
            if rng.random() < 0.75:
                return 'D'
            return 'C'
        else:
            # Opponent cooperated.
            if last_my == 'D':
                # If opponent remains cooperative despite our D, exploit a bit.
                if opp_rate >= 0.6 and n < 85 and rng.random() < 0.4:
                    return 'D'
                return 'C'
            return 'C'

    # --- Low-cooperation opponent: defect-heavy, rare probes ---
    if opp_rate >= 0.15:
        if last_op == 'C':
            # Reward occasional C with C, but not too generously.
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        if n < 90 and rng.random() < 0.08:
            return 'C'
        return 'D'

    # --- Nearly always defecting opponent ---
    if n < 90 and rng.random() < 0.03:
        return 'C'
    return 'D'
